const modal=document.querySelector("#bookingModal"),form=document.querySelector("#bookingForm");const names={swedish:"Swedish Massage",deep:"Deep Tissue Massage",beach:"Beach Massage",couples:"Couples Massage"};function openBooking(service="swedish",duration="60"){if(!modal||!form)return;modal.classList.add("open");document.body.style.overflow="hidden";if(form.service)form.service.value=service;if(form.duration)form.duration.value=duration}function closeBooking(){if(!modal)return;modal.classList.remove("open");document.body.style.overflow=""}document.addEventListener("click",e=>{const b=e.target.closest("[data-book]");if(b){e.preventDefault();openBooking(b.dataset.service||"swedish",b.dataset.duration||"60")}if(e.target.matches("[data-close]")||e.target===modal)closeBooking()});document.addEventListener("keydown",e=>{if(e.key==="Escape")closeBooking()});document.querySelectorAll(".faq-q").forEach(b=>b.addEventListener("click",()=>b.parentElement.classList.toggle("open")));document.querySelectorAll(".pay-card").forEach(c=>c.addEventListener("click",()=>{document.querySelectorAll(".pay-card").forEach(x=>x.classList.remove("selected"));c.classList.add("selected");c.querySelector("input").checked=true}));if(form)form.addEventListener("submit",async e=>{e.preventDefault();const d=new FormData(form);const payload={service:d.get("service"),duration:d.get("duration"),date:d.get("date"),time:d.get("time"),location:d.get("location"),name:d.get("name"),phone:d.get("phone"),email:d.get("email"),payment:d.get("payment"),notes:d.get("notes")||"",website:d.get("website")||"",source:location.href};const btn=form.querySelector('button[type="submit"]'),old=btn.textContent;btn.disabled=true;btn.textContent="Sending request…";form.querySelectorAll(".booking-error").forEach(x=>x.remove());try{const r=await fetch("/api/booking-request",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok)throw new Error(data.error||"Request failed");modal.querySelector(".booking-panel").innerHTML=`<div><p class="eyebrow">REQUEST RECEIVED</p><h2>We've got your St. Vincent & the Grenadines massage request.</h2><p>A confirmation was sent to <strong>${payload.email}</strong>. Your appointment remains pending until therapist availability, island routing and property access are confirmed.</p><p><strong>Reference: ${data.reference}</strong></p><div class="success-summary"><div><span>Service</span><strong>${names[payload.service]||payload.service}</strong></div><div><span>Duration</span><strong>${payload.duration} minutes</strong></div><div><span>Date</span><strong>${payload.date}</strong></div><div><span>Time</span><strong>${payload.time}</strong></div><div><span>Location</span><strong>${payload.location}</strong></div><div><span>Payment</span><strong>${payload.payment==="pay"?"Pay online after confirmation":"Pay in person"}</strong></div></div><div style="margin-top:18px;background:#edf8f6;padding:16px">We will contact you to confirm therapist availability and any island-transfer or access details before payment is requested.</div><button class="btn btn-dark" data-close style="margin-top:18px">Close</button></div>`}catch(ex){const box=document.createElement("div");box.className="booking-error";box.textContent="We couldn't send your request. Please try again or use the Need help button.";form.appendChild(box);btn.disabled=false;btn.textContent=old}});document.querySelectorAll("[data-gallery]").forEach(el=>el.addEventListener("click",()=>{const lb=document.querySelector("#lightbox"),im=document.querySelector("#lightboxImage");if(!lb||!im)return;im.src=el.dataset.gallery;lb.classList.add("open");document.body.style.overflow="hidden"}));document.addEventListener("click",e=>{const lb=document.querySelector("#lightbox");if(e.target.matches("[data-lightbox-close]")||e.target===lb){lb?.classList.remove("open");document.body.style.overflow=""}});(()=>{const d=document.createElement("div");d.className="contact-dock";d.innerHTML='<div class="contact-menu" hidden><span>Need help booking?</span><a href="https://wa.me/12428168286" target="_blank" rel="noopener"><b>WhatsApp</b><small>Message our concierge</small></a><a href="sms:+12428168286"><b>iMessage / Text</b><small>+1 (242) 816-8286</small></a></div><button class="contact-trigger" aria-label="Open booking help">Need help?</button>';document.body.appendChild(d);const m=d.querySelector(".contact-menu"),b=d.querySelector(".contact-trigger");b.onclick=()=>m.hidden=!m.hidden})();